/**
 * ============================================================
 * iPOS - POS Counter Management Models
 * ============================================================
 *
 * Backend: ASP.NET Core / .NET 10
 * Frontend: Angular 22
 *
 * SQL Server RowVersion is represented as a Base64 string.
 * ============================================================
 */

/**
 * POS Counter information returned by the backend.
 */
export interface PosCounter {
  id: number;
  branchId: number;

  /**
   * Automatically generated by the backend.
   * Read-only in the management interface.
   */
  code: string;

  /**
   * Required. Maximum 200 characters.
   */
  name: string;

  /**
   * Optional device identifier.
   * Maximum 200 ASCII characters.
   */
  deviceIdentifier: string | null;

  /**
   * Optional default warehouse.
   * Must belong to the same branch,
   * be active and allow sales.
   */
  defaultWarehouseId: number | null;

  /**
   * Counter activation status.
   */
  isActive: boolean;

  /**
   * SQL Server RowVersion serialized as Base64.
   */
  rowVersion: string;
}

/**
 * ============================================================
 * CREATE POS COUNTER
 * ============================================================
 *
 * POST /api/branches/{branchId}/pos-counters
 */
export interface CreatePosCounterRequest {
  name: string;
  deviceIdentifier: string | null;
  defaultWarehouseId: number | null;
}

/**
 * ============================================================
 * UPDATE POS COUNTER
 * ============================================================
 *
 * PUT /api/branches/{branchId}/pos-counters/{counterId}
 *
 * Counter Code, BranchId and IsActive are not editable.
 */
export interface UpdatePosCounterRequest {
  name: string;
  deviceIdentifier: string | null;
  defaultWarehouseId: number | null;

  /**
   * Latest RowVersion returned by the backend.
   *
   * An outdated RowVersion produces HTTP 409 Conflict.
   */
  rowVersion: string;
}

/**
 * ============================================================
 * POS COUNTER DIRECTORY QUERY PARAMETERS
 * ============================================================
 *
 * GET /api/branches/{branchId}/pos-counters
 *
 * All properties are optional.
 */
export interface GetPosCountersParams {
  includeInactive?: boolean;

  code?: string;
  name?: string;
  deviceIdentifier?: string;

  defaultWarehouseId?: number;
  isActive?: boolean;

  sortBy?: string;
  sortDirection?: 'asc' | 'desc';

  pageNumber?: number;
  pageSize?: number;
}

/**
 * ============================================================
 * POS COUNTER PAGINATED RESPONSE
 * ============================================================
 *
 * Backend:
 * GetPosCountersResult.cs
 *
 * C#:
 * PosCounterPagedResult
 *
 * This interface matches the backend response contract.
 */
export interface PosCounterPagedResult {
  /**
   * POS Counters belonging to the requested page.
   */
  items: PosCounter[];

  /**
   * Total number of matching records.
   */
  totalCount: number;

  /**
   * Current page number (one-based).
   */
  pageNumber: number;

  /**
   * Number of records requested per page.
   */
  pageSize: number;

  /**
   * Total number of available pages.
   */
  totalPages: number;

  /**
   * Whether a previous page exists.
   */
  hasPreviousPage: boolean;

  /**
   * Whether a next page exists.
   */
  hasNextPage: boolean;
}

/**
 * ============================================================
 * CHANGE POS COUNTER STATUS
 * ============================================================
 *
 * Reserved for future backend implementation.
 *
 * The current Update POS Counter API does not support
 * activation or deactivation.
 */
export interface ChangePosCounterStatusRequest {
  rowVersion: string;
}